import java.io.FileWriter;

public class Program {
    public static void main(String[] args) {
        try {
            FileWriter writer = new FileWriter("test.txt");
            writer.write("Hello");
            writer.close();
            System.out.println("File written");
        } catch (Exception e) {
            System.out.println("Error");
        }
    }
}

